/** Rust: `win_wallpaper::WallpaperFile` */
export interface WallpaperFile {
  name: string;
  path: string;
  kind: WallpaperKind;
  bytes: number;
}

/** Rust: `win_wallpaper::WallpaperKind` */
export type WallpaperKind =
  | "image"
  | "video"
  | "html";

/** Rust: `win_wallpaper::WallpaperSettings` */
export interface WallpaperSettings {
  /** Draw the Lens wallpaper behind the desktop icons. OFF by default. */
  enabled: boolean;
  /** File name inside the wallpapers folder ("" = none chosen yet). */
  file: string;
  /** "cover" | "contain" | "fill" | "center" */
  fit: string;
  /** 0–40 px */
  blur: number;
  /** 0–80 % darkening overlay */
  dim: number;
  /** 0–200 % */
  saturation: number;
  /** Pause video / HTML while a maximised or fullscreen window covers the monitor. */
  pauseWhenCovered: boolean;
  /** Pause video / HTML while running on battery. */
  pauseOnBattery: boolean;
  /** Last dominant colour the surface measured from the displayed wallpaper ("" = unknown). */
  accentHex: string;
  /** Apply `accent_hex` as the Lens accent whenever the wallpaper changes. */
  followAccent: boolean;
}

/** Rust: `win_wallpaper::WallpaperState` */
export interface WallpaperState {
  settings: WallpaperSettings;
  path: string | null;
  kind: WallpaperKind | null;
  attached: boolean;
  folder: string;
}

/** Rust: `config::WidgetsConfig` */
export interface WidgetsConfig {
  enabledWidgets: string[];
  notes: string;
}

/** Rust: `win_system_modules::WifiNetwork` */
export interface WifiNetwork {
  ssid: string;
  /** 0–100 as reported by Windows. */
  signal: number;
  /** 0–4 bars. */
  bars: number;
  secured: boolean;
  connected: boolean;
  /** A saved Windows profile exists, so Lens can connect without a password. */
  hasProfile: boolean;
}

/** Rust: `win_system_modules::WifiState` */
export interface WifiState {
  available: boolean;
  /** Why Wi-Fi is unavailable, in plain words (empty when available). */
  reason: string;
  /** None when the radio state could not be read. */
  radioOn: boolean | null;
  adapter: string;
  connectedSsid: string | null;
  networks: WifiNetwork[];
}

/** Rust: `win_windhawk::WindhawkStatus` */
export interface WindhawkStatus {
  installed: boolean;
  exePath: string | null;
  modSourcePath: string;
  modInstalledInWindhawk: boolean;
}

/** Rust: `config::WindowControlsConfig` */
export interface WindowControlsConfig {
  enabled: boolean;
  style: string;
  order: string;
  position: string;
  frameBorderEnabled: boolean;
  frameStyle: string;
  excludedProcesses: string[];
}

/** Rust: `win_rules::WindowRule` */
export interface WindowRule {
  /** Process file name, case-insensitive, with or without ".exe" ("WindowsTerminal", "code.exe"). */
  match: string;
  /** Window opacity in percent (40–100). `None` follows the global setting. */
  opacity: number | null;
  /** "default" | "none" | "#RRGGBB" */
  frame: string;
  /** "default" | "square" | "small" | "round" */
  corners: string;
  /** Lens leaves this app's windows completely alone. */
  exclude: boolean;
}

/** Rust: `win_theme::WindowsThemeInfo` */
export interface WindowsThemeInfo {
  accentHex: string;
  accentR: number;
  accentG: number;
  accentB: number;
  appsUseLightTheme: boolean;
  systemUsesLightTheme: boolean;
  transparencyEnabled: boolean;
}

/**
 * Result of talking to the Windows notification listener.
 * Rust: `win_notifications::WindowsToastResult`
 */
export interface WindowsToastResult {
  /** "ok" | "needs-access" | "denied" | "unavailable" */
  status: string;
  /** Plain-language explanation when status is not "ok" (empty otherwise). */
  reason: string;
  items: NotificationItem[];
}

/** Rust: `win_training::WorkflowMacro` */
export interface WorkflowMacro {
  id: string;
  name: string;
  createdAt: number;
  steps: WorkflowMacroStep[];
}

/** Rust: `win_training::WorkflowMacroStep` */
export interface WorkflowMacroStep {
  kind: string;
  label: string;
  payload: string;
}

/** Rust: `win_workspaces::WorkspaceDef` */
export interface WorkspaceDef {
  id: string;
  name: string;
  color: string;
  /** Tiling layout for this workspace; "" uses the global tiling layout. */
  layout: string;
  /** Apps that open on this workspace (process names, e.g. "spotify.exe"). */
  apps: string[];
  /** Apps that always float while on this workspace. */
  floatApps: string[];
}

/** Rust: `win_workspaces::WorkspaceStatus` */
export interface WorkspaceStatus {
  enabled: boolean;
  /** Backend in use: "virtual-desktops" | "groups". */
  mode: string;
  active: number;
  workspaces: WorkspaceView[];
  /** Number of Windows virtual desktops (virtual-desktops mode). */
  desktopCount: number;
  appRulesActive: boolean;
  /** Plain-language explanation of any limitation. */
  note: string;
}

/** Rust: `win_workspaces::WorkspaceView` */
export interface WorkspaceView {
  index: number;
  id: string;
  name: string;
  color: string;
  layout: string;
  /** Known only in groups mode. */
  windowCount: number | null;
}

/** Rust: `win_workspaces::WorkspacesConfig` */
export interface WorkspacesConfig {
  enabled: boolean;
  /** "auto" | "virtual-desktops" | "groups" */
  mode: string;
  /** When an app with a rule opens, switch to its workspace (true) or leave it there minimised. */
  followAssigned: boolean;
  workspaces: WorkspaceDef[];
}

